/* Current-task delivery requirements, independent positions and company-library navigation. */
function createDeliveryWorkspace(ctx){
 const {state,getUI,task,assets,product,imageSrc,esc,icon,btn,heading,empty,artwork,purposeName,render,persist,toast,openModal,closeModal,showAsset,showReviewAsset,syncDraft,freshDraft,canUse,production:p,company:c}=ctx;
 let picker=null;
 const slots=()=>p.slots(task());
 const available=row=>assets().filter(a=>canUse(a)&&p.matches(a,row)&&!Object.entries(task().deliverySelections).some(([key,id])=>key!==row.key&&id===a.id));
 function adoptVersion(id,key){c.requireRight('adopt');const a=assets().find(a=>a.id===id);const row=key?slots().find(r=>r.key===key):slots().find(r=>!r.asset&&available(r).some(x=>x.id===id))||slots().find(r=>r.asset?.id===id);if(!row&&canUse(a)&&!key){const occupied=slots().find(r=>p.matches(a,r));if(occupied){chooseVersion(occupied.key,id);return false;}}if(!row||!canUse(a)){toast('没有可用的匹配位置，请核对模块和规格。');return false;}p.adopt(task(),row.key,id);persist();return true;}
 function slotAction(row){
  if(available(row).length)return{state:'unpicked',status:'待采用',label:'选择采用',note:`${available(row).length} 个匹配批准版本`,action:'delivery-choose',id:row.key};
  const list=assets().filter(a=>p.matches(a,row)),pending=list.find(a=>a.status==='pending');if(pending)return{state:'pending',status:'待终审',label:'前往终审',note:'已有匹配素材，通过终审后可采用',action:'delivery-review',id:pending.id};
  const checking=list.find(a=>a.status==='checking');if(checking)return{state:'checking',status:'初检中',label:'查看初检',note:'正在进行模拟 AI 初检',action:'delivery-review',id:checking.id};
  const issue=list.find(a=>['rejected','blocked','check_failed'].includes(a.status));if(issue)return{state:issue.status,status:{rejected:'已驳回',blocked:'已拦截',check_failed:'初检异常'}[issue.status],label:'查看问题',note:issue.reason||issue.precheck?.message||'查看问题后调整制作',action:'delivery-review',id:issue.id};
  return{state:'empty',status:'未制作',label:row.purpose==='video'?'制作视频':'制作此位置',note:list.some(a=>canUse(a))?'现有批准版本已用于其他位置，需补做一份':'暂无符合模块与规格的素材',action:'delivery-create',id:row.key};
 }
 function position(row){const a=row.asset,next=!a?slotAction(row):null,status=a?'adopted':next.state;return `<section class="delivery-position" data-slot="${row.key}" data-delivery-state="${status}"><div class="delivery-position-head"><h3>${esc(row.module)}${row.count>1?' · '+(row.index+1):''}</h3><span class="delivery-state ${a?'is-ready':status==='empty'?'is-empty':['blocked','rejected','check_failed'].includes(status)?'is-problem':'is-progress'}">${a?'已采用':next.status}</span></div><p class="delivery-slot-spec">${esc(row.ratio)} · ${row.purpose==='video'?esc(row.quality):parseInt(row.quality)/1024+'K'}${row.purpose==='video'?' · '+row.duration+'s':''}</p>${a?`<div class="delivery-picked"><button class="delivery-thumb" data-action="asset-detail" data-id="${a.id}" aria-label="查看${esc(a.name)}"><img src="${imageSrc(a.image)}" alt="${esc(a.name)}"></button><div><h4 title="${esc(a.name)}">${esc(a.name)}</h4><p>V${a.version}${a.media==='video'?' · 分镜示例':''}</p></div></div><div class="delivery-position-actions"><button class="text-button" data-action="asset-detail" data-id="${a.id}">查看版本</button><button class="text-button" data-action="delivery-choose" data-id="${row.key}" ${c.can('adopt')?'':'disabled'}>更换版本</button></div>`:`<div class="delivery-gap"><p>${esc(next.note||'待处理')}</p><button class="btn sm" data-action="${next.action}" data-id="${next.id}" ${next.action==='delivery-create'&&!c.can('create')||next.action==='delivery-choose'&&!c.can('adopt')?'disabled':''}>${next.label}${icon('arrow')}</button></div>`}</section>`;}
 function renderPage(){
  const ui=getUI(),rows=slots(),ready=rows.filter(r=>r.asset).length,missing=rows.length-ready,global=ui.deliveryView==='company',visible=ui.deliveryOnlyMissing?rows.filter(r=>!r.asset):rows;
  const tabs=`<div class="delivery-view-switch" role="group" aria-label="资产与交付视图"><button class="filter ${!global?'active':''}" data-action="delivery-view" data-id="list" aria-pressed="${!global}">本次交付</button><button class="filter ${global?'active':''}" data-action="delivery-view" data-id="company" aria-pressed="${global}">公司素材</button></div>`;
  const actions=`<div class="row delivery-overview-actions"><button class="btn" data-action="requirements-open" ${c.can('create')?'':'disabled'}>${icon('settings')}配置交付要求</button><button class="btn primary delivery-export" data-action="export" ${ready&&c.can('download')?'':'disabled'}>${icon('download')}${missing?'导出部分交付包':'导出完整交付包'}</button></div>`;
  return heading('资产与交付','')+`<div class="delivery-toolbar">${tabs}${global?'<span class="company-scope-note">跨任务浏览 · 本机团队演示</span>':actions}</div>${global?ctx.companyLibrary():`<section class="delivery-overview"><p class="delivery-progress" role="status">${task().products.length} 个 SKU <span>·</span> 已配齐 <strong>${ready}/${rows.length}</strong> <span>·</span> ${missing?`待补齐 ${missing}`:'全部配齐'}</p><label class="delivery-gap-filter"><input id="delivery-only-missing" type="checkbox" ${ui.deliveryOnlyMissing?'checked':''}>只看待补齐${ui.deliveryOnlyMissing?` <span>(${visible.length})</span>`:''}</label></section><div class="delivery-products">${task().products.map(pid=>{const own=rows.filter(r=>r.product===pid),shown=visible.filter(r=>r.product===pid),count=own.filter(r=>r.asset).length;if(!shown.length)return '';return `<section class="delivery-product"><header class="delivery-product-heading"><div><h2>${esc(product(pid).name)}</h2><p>${esc(product(pid).sku)}</p></div><span class="delivery-product-count">${count}/${own.length} 已配齐</span></header><div class="delivery-positions">${shown.map(position).join('')}</div></section>`;}).join('')}</div>${visible.length?'':`<div class="empty-state"><h3>当前任务已全部配齐</h3><p>可以查看已采用版本，或导出完整交付包。</p><button class="btn sm" data-action="delivery-show-all">查看全部位置</button></div>`}`}`;
 }
 function chooseVersion(key,preferred){c.requireRight('adopt');const row=slots().find(r=>r.key===key);if(!row)return;const list=available(row);if(!list.length){toast('没有模块、规格及 SKU 均匹配的批准版本。');return;}const selected=list.find(a=>a.id===preferred)||row.asset||list[0];picker={taskId:task().id,key,selected:selected.id};openModal('选择交付版本',`<p class="delivery-picker-context">${esc(product(row.product).name)} · ${esc(row.module)} · 第 ${row.index+1} 份</p><p class="company-form-intro">${esc(row.ratio)} · ${esc(row.quality)}${row.purpose==='video'?' · '+row.duration+'s':''}。仅显示匹配且未被其他位置采用的批准版本。</p><div class="delivery-version-options">${list.map(a=>`<label class="delivery-version-option"><input type="radio" name="delivery-version" value="${a.id}" ${a.id===selected.id?'checked':''}><img src="${imageSrc(a.image)}" alt="${esc(a.name)}"><span><strong>${esc(a.name)}</strong><small>V${a.version}${row.asset?.id===a.id?' · 当前采用':''}</small></span></label>`).join('')}</div>`,btn('取消','close-modal')+btn('确认采用','delivery-apply','primary'));document.querySelector('.overlay .modal').classList.add('delivery-picker');}
 function createDraft(key){c.requireRight('create');const row=slots().find(r=>r.key===key);if(!row)return;syncDraft();const ui=getUI(),d={...freshDraft(row.product)};p.applyRequirement(d,row);c.bindDraft(d);if(c.draftProblem(d)){delete d.templateId;delete d.templateVersion;c.bindDraft(d);}const node={id:'g'+(Math.max(0,...task().nodes.map(n=>+n.id.slice(1)))+1),x:345,y:70,draft:d};task().nodes.push(node);ui.node=node.id;task().draft=p.copy(d);ui.page='studio';ui.view='page';ui.inspector=false;ui.scope='current';ui.tab='all';ui.filter='all';ui.selected=[];persist();render();document.querySelector('#prompt')?.focus({preventScroll:true});toast('已带入此交付位置的模块和规格。');}
 function handleAction(action,id){if(!action.startsWith('delivery-'))return false;try{switch(action){
  case 'delivery-view':getUI().deliveryView=id==='company'?'company':'list';render();break;
  case 'delivery-show-all':getUI().deliveryOnlyMissing=false;render();document.querySelector('#delivery-only-missing')?.focus({preventScroll:true});break;
  case 'delivery-choose':chooseVersion(id);break;
  case 'delivery-adopt':{const a=assets().find(x=>x.id===id),row=slots().find(r=>!r.asset&&available(r).some(x=>x.id===a?.id));if(row)chooseVersion(row.key,id);else toast('没有匹配的交付位置。');break;}
  case 'delivery-apply':c.requireRight('adopt');if(!picker||picker.taskId!==task().id)throw new Error('任务已变化，请重新选择。');if(adoptVersion(picker.selected,picker.key)){closeModal();render();toast('此位置已采用，其他位置保持不变。');}break;
  case 'delivery-create':createDraft(id);break;
  case 'delivery-review':{const a=assets().find(a=>a.id===id);if(a){getUI().page='review';getUI().reviewFilter=a.status;render();showReviewAsset(id);}break;}
 } }catch(e){toast(e.message);}return true;}
 function handleChange(target){if(target.id==='delivery-only-missing'){getUI().deliveryOnlyMissing=target.checked;render();document.querySelector('#delivery-only-missing')?.focus({preventScroll:true});return true;}if(target.name==='delivery-version'){if(picker)picker.selected=target.value;return true;}return false;}
 return{renderPage,slots,adoptVersion,handleAction,handleInput:()=>false,handleChange};
}
